-- M5 contract DDL v1. Cross-owner UUIDs are references, never foreign keys.
SET LOCAL timezone = 'UTC';
CREATE TABLE assignment.routing_rules (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), service_id uuid NOT NULL, team_id uuid NOT NULL, level text NOT NULL CHECK(level IN ('L1','L2')), required_skills text[] NOT NULL, active boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE ON assignment.routing_rules TO helpdesk_m5;
CREATE TABLE assignment.rosters (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), subject_id uuid NOT NULL, team_id uuid NOT NULL, skills text[] NOT NULL, available_from timestamptz NOT NULL, available_until timestamptz NOT NULL, CHECK(available_until>available_from));
GRANT SELECT, INSERT, UPDATE ON assignment.rosters TO helpdesk_m5;
CREATE TABLE assignment.load_projection (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL UNIQUE, source_version bigint NOT NULL CHECK(source_version>0), assignee_id uuid, state text NOT NULL);
GRANT SELECT, INSERT, UPDATE ON assignment.load_projection TO helpdesk_m5;
CREATE TABLE assignment.assignment_proposals (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL, ticket_version bigint NOT NULL CHECK(ticket_version>0), assignee_id uuid NOT NULL, team_id uuid NOT NULL, explanation text NOT NULL);
GRANT SELECT, INSERT ON assignment.assignment_proposals TO helpdesk_m5;
CREATE TABLE assignment.idempotency_records (actor_scope text NOT NULL, command text NOT NULL, target text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), payload_digest bytea NOT NULL CHECK(octet_length(payload_digest)=32), response_status integer NOT NULL CHECK(response_status BETWEEN 200 AND 299), response_body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, PRIMARY KEY(actor_scope,command,target,key));
CREATE TABLE assignment.outbox (event_id uuid PRIMARY KEY, event_type text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), occurred_at timestamptz NOT NULL, correlation_id uuid NOT NULL, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'), digest bytea NOT NULL CHECK(octet_length(digest)=32));
CREATE TABLE assignment.outbox_delivery (event_id uuid NOT NULL REFERENCES assignment.outbox(event_id), consumer_id text NOT NULL CHECK(consumer_id ~ '^M[1-9]$'), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), lease_until timestamptz, acked_at timestamptz, last_error_code text, PRIMARY KEY(event_id,consumer_id), CHECK((state='ACKED')=(acked_at IS NOT NULL)));
CREATE TABLE assignment.inbox (consumer_id text NOT NULL, event_id uuid NOT NULL, digest bytea NOT NULL CHECK(octet_length(digest)=32), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE assignment.audit_intents (id uuid PRIMARY KEY, actor_id uuid NOT NULL, action text NOT NULL, object_id uuid NOT NULL, scope text NOT NULL, reason text NOT NULL, outcome text NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON assignment.idempotency_records, assignment.outbox, assignment.inbox, assignment.audit_intents TO helpdesk_m5;
GRANT SELECT, INSERT, UPDATE ON assignment.outbox_delivery TO helpdesk_m5;
CREATE INDEX ON assignment.outbox_delivery (state, lease_until, event_id) WHERE state<>'ACKED';
REVOKE ALL ON ALL TABLES IN SCHEMA assignment FROM PUBLIC;
